// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/ERC20.sol";

contract ERC20VulnerabilityTest is Test {
    ERC20 token;
    address owner = address(0x1);
    address recipient = address(0x2);
    address attacker = address(0x3);

    function setUp() public {
        vm.prank(owner);
        token = new ERC20(1000);
    }

    function testMessagePaddingVulnerability() public {
        // Transfer tokens to attacker for testing
        vm.prank(owner);
        token.transfer(attacker, 500);
        uint256 initialAttackerBalance = token.balanceOf(attacker);
        uint256 initialZeroAddressBalance = token.balanceOf(address(0));

        // Attempt transfer to zero address with padded calldata
        vm.prank(attacker);
        (bool success, ) = address(token).call(
            abi.encodeWithSelector(
                token.transfer.selector,
                bytes32(uint256(uint160(address(0)))),
                100
            )
        );

        // Validate results based on vulnerability presence
        if (success) {
            // Vulnerability exists: transfer to zero address succeeded
            uint256 newZeroAddressBalance = token.balanceOf(address(0));
            assertGt(
                newZeroAddressBalance,
                initialZeroAddressBalance,
                "Zero address received tokens"
            );

            uint256 newAttackerBalance = token.balanceOf(attacker);
            assertEq(
                newAttackerBalance,
                initialAttackerBalance - 100,
                "Attacker balance not reduced"
            );

            // Fail explicitly to mark vulnerability
            fail("Vulnerability exploited: transfer to zero address succeeded");
        } else {
            // Vulnerability patched: transaction should revert
            uint256 finalZeroAddressBalance = token.balanceOf(address(0));
            assertEq(
                finalZeroAddressBalance,
                initialZeroAddressBalance,
                "Zero address balance changed unexpectedly"
            );

            uint256 finalAttackerBalance = token.balanceOf(attacker);
            assertEq(
                finalAttackerBalance,
                initialAttackerBalance,
                "Attacker balance changed unexpectedly"
            );
        }
    }
}
